use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut jobs = Vec::new();
    for line in input.as_array() {
        let arrival = line[0].as_i64().unwrap();
        let duration = line[1].as_i64().unwrap();
        jobs.push((arrival, duration));
    }

    jobs.sort_by_key(|&(arrival, _)| arrival);

    let mut finish_times = Vec::new();
    let mut current_finish = 0;
    for job in jobs {
        current_finish += job.1;
        finish_times.push(current_finish);
    }

    finish_times.sort_unstable();
    finish_times.reverse();

    serde_json::Value::from(finish_times)
}

fn main() {
    let input = serde_json::Value::from("{\"input\":[[0,3],[1,2],[8,1]],\"expected\":[3,5,9]}");
    let result = solve(input);
    println!("{:?}", result);
}
